"""QDPT active-space effective Hamiltonian g_eff (sectors 0 to max_vertex), spin-free (spatial).

Machine-generated from the Wick-contracted MP2/MP3 downfolding diagrams, for
max vertex rank 2 or 3,
with the antisymmetrized-diagram terms collapsed to spatial-orbital
tensors and summed over spin. Do not edit by hand. Called from the QDPT driver,
perturbative.build_effective_hamiltonian.
"""
import numpy as np

def eval_pt2_v2_spinfree(g_spatial, h1_spatial, eps_spatial, occ_idx, act_idx, virt_idx, act_occ_idx, act_vir_idx, n_spin_orbs, shift=None):
    import numpy as np
    g = g_spatial
    h1 = h1_spatial
    eps_spin = eps_spatial
    g_eff = {n: np.zeros((len(act_idx),) * (2*n)) for n in range(1, 3)}
    g_eff[0] = 0.0
    _cache = {}
    _use_count = {
        'int_0': 1,
        'int_1': 1,
        'int_2': 1,
        'int_3': 1,
        'int_4': 1,
        'int_5': 1,
        'int_6': 1,
        'int_7': 1,
        'int_8': 1,
        'int_9': 1,
        'int_10': 1,
        'int_11': 1,
        'int_12': 1,
        'int_13': 1,
        'int_14': 1,
        'int_15': 1,
        'int_16': 1,
        'int_17': 1,
        'int_18': 1,
        'int_19': 1,
        'int_20': 1,
        'int_21': 1,
        'int_22': 1,
        'int_23': 1,
        'int_24': 1,
        'int_25': 1,
        'int_26': 1,
        'int_27': 1,
        'int_28': 1,
        'int_29': 1,
        'int_30': 1,
        'int_31': 1,
        'int_32': 1,
    }

    # Sector: 0-Body | Term: +2.0000 * h1(i,i)
    b0 = h1[np.ix_(occ_idx, occ_idx)]
    g_eff[0] += 2.0 * np.einsum('AA->', b0, optimize=True)

    # Sector: 0-Body | Term: +1.5000 * g(j,i,j,i)
    b0 = g[np.ix_(occ_idx, occ_idx, occ_idx, occ_idx)]
    g_eff[0] += 1.5 * np.einsum('BABA->', b0, optimize=True)

    # Sector: 0-Body | Term: -1.0000 * g(j,i,i,j)
    b0 = g[np.ix_(occ_idx, occ_idx, occ_idx, occ_idx)]
    g_eff[0] += -1.0 * np.einsum('BAAB->', b0, optimize=True)

    # Sector: 0-Body | Term: +0.5000 * g(i,j,i,j)
    b0 = g[np.ix_(occ_idx, occ_idx, occ_idx, occ_idx)]
    g_eff[0] += 0.5 * np.einsum('ABAB->', b0, optimize=True)

    # Sector: 1-Body | Term: +1.0000 * h1(p,q)
    b0 = h1[np.ix_(act_idx, act_idx)]
    g_eff[1] += 1.0 * np.einsum('AB->AB', b0, optimize=True)

    # Sector: 1-Body | Term: -1.0000 * g(i,p,q,i)
    b0 = g[np.ix_(occ_idx, act_idx, act_idx, occ_idx)]
    g_eff[1] += -1.0 * np.einsum('ABCA->BC', b0, optimize=True)

    # Sector: 1-Body | Term: +1.0000 * g(i,p,i,q)
    b0 = g[np.ix_(occ_idx, act_idx, occ_idx, act_idx)]
    g_eff[1] += 1.0 * np.einsum('ABAC->BC', b0, optimize=True)

    # Sector: 1-Body | Term: +1.0000 * g(p,i,q,i)
    b0 = g[np.ix_(act_idx, occ_idx, act_idx, occ_idx)]
    g_eff[1] += 1.0 * np.einsum('BACA->BC', b0, optimize=True)

    # Sector: 2-Body | Term: +1.0000 * g(p,q,r,s)
    b0 = g[np.ix_(act_idx, act_idx, act_idx, act_idx)]
    g_eff[2] += 1.0 * np.einsum('ABCD->ABCD', b0, optimize=True)

    # --- Skeleton 94bc3a09 contains 1 permutations ---
    # Base Term: +0.7500 * g(a,b,j,i) * g(j,i,a,b) / E_corr + e_j + e_i - e_a - e_b
    g_temp = {0: np.zeros((len(act_idx),) * 0)}
    b0_full = g[np.ix_(virt_idx, virt_idx, occ_idx, occ_idx)]
    b1_full = g[np.ix_(occ_idx, occ_idx, virt_idx, virt_idx)]
    if 'int_0' not in _cache:
        I1 = np.zeros(())
        for i_a in range(len(virt_idx)):
            b0 = b0_full[i_a, :, :, :]
            b1 = b1_full[:, :, i_a, :]
            d0 = (eps_spin[occ_idx] + (shift / 2 if shift is not None else 0.0))[None, :, None] + (eps_spin[occ_idx] + (shift / 2 if shift is not None else 0.0))[None, None, :] - eps_spin[virt_idx[i_a]] - eps_spin[virt_idx][:, None, None]
            d0[np.abs(d0) < 1e-12] = 1e-12
            b0 = b0 / d0
            num = np.einsum('BDC,DCB->BCD', b0, b1, optimize=True)
            I1 += np.einsum('BCD->', num, optimize=True)
        _cache['int_0'] = I1
    I1 = _cache['int_0']
    g_temp[0] += 0.75 * np.einsum('->', I1, optimize=True)
    _use_count['int_0'] -= 1
    if _use_count['int_0'] == 0:
        del _cache['int_0']
    # Projecting permutation: +0.7500 * g(a,b,j,i) * g(j,i,a,b) / E_corr + e_j + e_i - e_a - e_b
    g_eff[0] += 1.000000000000 * g_temp[0]

    # --- Skeleton 94bc3a09 contains 1 permutations ---
    # Base Term: -0.5000 * g(a,b,j,i) * g(j,i,b,a) / E_corr + e_j + e_i - e_a - e_b
    g_temp = {0: np.zeros((len(act_idx),) * 0)}
    b0_full = g[np.ix_(virt_idx, virt_idx, occ_idx, occ_idx)]
    b1_full = g[np.ix_(occ_idx, occ_idx, virt_idx, virt_idx)]
